from pathlib import Path
import json, csv, collections, re
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'data/app-data.json').read_text(encoding='utf-8'))
core=D['core']['days']; days=D['resources']['days']; stage=D['resources']['stage47']
assign=stage['daily_assignments']; cat=stage['catalog']
DATE='2026-11-08'

def words(s): return len(re.findall(r"\b[\w’'-]+\b", str(s or '')))
# Full day-by-day external companion register (84 rows).
with (ROOT/'STAGE47_RESOURCE_MAPPING_UZ.csv').open('w',encoding='utf-8-sig',newline='') as f:
    fields=['day','week','theme','task1_visual_type','resource_id','resource_title','provider','official_url','level_estimate','level_basis','duration_note','segment_start','segment_end','listening_focus','study_task','transcript_caption_status','embed_mode','age_suitability','required_or_optional','in_app_fallback','repeat_design','last_checked_date']
    w=csv.DictWriter(f,fieldnames=fields); w.writeheader()
    for i,(r,a) in enumerate(zip(days,assign)):
        c=core[i]; t1=r['resources']['writing']['task1']
        w.writerow({'day':i+1,'week':c['week'],'theme':c['theme'],'task1_visual_type':t1['type'],'resource_id':a['resource_id'],'resource_title':a['title'],'provider':a['provider'],'official_url':a['url'],'level_estimate':a['level_estimate'],'level_basis':a['level_basis'],'duration_note':a['duration_note'],'segment_start':a.get('segment_start') or '','segment_end':a.get('segment_end') or '','listening_focus':a['listening_focus'],'study_task':a['study_task'],'transcript_caption_status':a['transcript_caption_status'],'embed_mode':a['embed_mode'],'age_suitability':a['age_suitability'],'required_or_optional':a['required_or_optional'],'in_app_fallback':f"Day {i+1} original MP3 + script + {len(c['listening']['questions'])} questions",'repeat_design':a['repeat_design'],'last_checked_date':DATE})
# 336-row four-skill in-app resource audit.
with (ROOT/'STAGE47_336_SKILL_RESOURCE_AUDIT_UZ.csv').open('w',encoding='utf-8-sig',newline='') as f:
    fields=['day','week','theme','skill','resource_title','primary_in_app_material','supporting_materials','item_count','word_or_audio_length','required_output','external_companion_url','source_and_rights','verification_status','last_checked_date']
    w=csv.DictWriter(f,fieldnames=fields); w.writeheader()
    for i,(r,c,a) in enumerate(zip(days,core,assign), start=1):
        rr=r['resources']; cc=c
        rd=rr['reading']; li=rr['listening']; wr=rr['writing']; sp=rr['speaking']
        records=[]
        records.append({'skill':'Reading','resource_title':cc['reading']['title'],'primary_in_app_material':f"Original passage: {words(cc['reading']['passage'])} words",'supporting_materials':f"{len(cc['reading']['questions'])} questions; facts/evidence map; weekly source pack {cc['reading'].get('weekly_source_pack','—')}",'item_count':len(cc['reading']['questions']),'word_or_audio_length':words(cc['reading']['passage']),'required_output':'; '.join(rd.get('daily_reading_output',[])),'external_companion_url':rd.get('official_ielts',''),'source_and_rights':'Original IELTS Boost fictional practice passage/questions; external sources linked only, not copied.','verification_status':'In-app passage + questions present; answer/evidence dataset inherited from Stage 35 QA.'})
        records.append({'skill':'Listening','resource_title':cc['listening']['title'],'primary_in_app_material':f"Original MP3: {cc['listening']['audio_asset']} ({round(cc['listening']['audio_duration_seconds'])} sec); original script {words(cc['listening']['script'])} words",'supporting_materials':f"{len(cc['listening']['questions'])} questions; dictation chunk; transcript/script; Stage 47 selected companion: {a['title']} ({a['provider']})",'item_count':len(cc['listening']['questions']),'word_or_audio_length':round(cc['listening']['audio_duration_seconds']),'required_output':'Listen to the in-app audio, answer questions, record evidence, review transcript; external companion is optional.', 'external_companion_url':a['url'],'source_and_rights':'In-app audio/script are original synthetic-voice practice; external media remains on official provider page.','verification_status':'Original MP3/script/questions present; audio file non-empty; companion exact official URL mapped.'})
        records.append({'skill':'Writing','resource_title':f"Task 1: {wr['task1']['title']} | Task 2: {wr['task2_prompt'][:80]}",'primary_in_app_material':f"Original Task 1 {wr['task1']['type']} visual + data; Task 2 original prompt",'supporting_materials':f"Task 1 min {cc['writing']['task1_target_words']} words; Task 2 min {cc['writing']['task2_target_words']} words; 4-criterion rubric; planning/draft/rewrite history",'item_count':2,'word_or_audio_length':f"Task1≥{cc['writing']['task1_target_words']}; Task2≥{cc['writing']['task2_target_words']}",'required_output':'Two separate outputs according to the day plan: Task 1 report and/or Task 2 essay with criterion review.', 'external_companion_url':wr.get('official_task_samples',''),'source_and_rights':'All 84 Task 1 datasets and 84 Task 2 prompts are original fictional practice; no Barron’s or Cambridge material copied.','verification_status':'Task 1 visual dataset structurally validated by Stage 47 engine; Task 2 prompt present.'})
        records.append({'skill':'Speaking','resource_title':cc['speaking']['part2'][:90],'primary_in_app_material':f"Part 1: {len(cc['speaking']['part1'])} prompts; Part 2 cue card; Part 3: {len(cc['speaking']['part3'])} prompts",'supporting_materials':'Daily chunk; follow-up rule; audio recording/replay; transcript and four-criterion self-review', 'item_count':len(cc['speaking']['part1'])+1+len(cc['speaking']['part3']),'word_or_audio_length':'Part 2 speaking response target 1–2 minutes (practice guidance)','required_output':cc['speaking'].get('daily_recording_output','Record and review a spoken response.'),'external_companion_url':sp.get('official_speaking_sample',''),'source_and_rights':'Original IELTS Boost prompts; official public criteria/help pages linked, not reproduced.','verification_status':'All day-specific prompts present; transcript/audio browser support remains device-dependent.'})
        for rec in records:
            w.writerow({'day':i,'week':cc['week'],'theme':cc['theme'],'last_checked_date':DATE,**rec})
# Task 1 visual-data audit sheet.
with (ROOT/'STAGE47_TASK1_84_VISUAL_AUDIT_UZ.csv').open('w',encoding='utf-8-sig',newline='') as f:
    fields=['day','week','visual_type','title','prompt','unit','data_structure','data_points_or_features','number_of_series','provenance','stage47_validator','notes']
    w=csv.DictWriter(f,fieldnames=fields); w.writeheader()
    for i,r in enumerate(days, start=1):
        s=r['resources']['writing']['task1']; typ=s['type']
        if typ in ['line_graph','bar_chart','table']:
            ds='; '.join(f"{x.get('name','Series')}: {', '.join(map(str,x.get('values',[])))}" for x in s.get('series',[]))
            count=sum(len(x.get('values',[])) for x in s.get('series',[])); ns=len(s.get('series',[]))
        elif typ=='pie_chart': ds='; '.join(f"{a}: {b}" for a,b in zip(s.get('labels',[]),s.get('values',[]))); count=len(s.get('values',[])); ns=1
        elif typ=='process': ds=' → '.join(s.get('steps',[])); count=len(s.get('steps',[])); ns=1
        else: ds='; '.join(f"{a} → {b}" for a,b in zip(s.get('before',[]),s.get('after',[]))); count=len(s.get('before',[])); ns=2
        w.writerow({'day':i,'week':r['week'],'visual_type':typ,'title':s['title'],'prompt':s['prompt'],'unit':s.get('display_units') or s.get('unit',''),'data_structure':ds,'data_points_or_features':count,'number_of_series':ns,'provenance':s.get('data_note',''),'stage47_validator':'PASS (84-day structural validator)' ,'notes':'Original fictional IELTS-style practice dataset; not official statistics and not copied from Barron’s/Cambridge.'})
# Curated catalog snapshot with all metadata and provider directory.
(ROOT/'data/stage47-resource-catalog.json').write_text(json.dumps({'catalog':cat,'optional_discovery':stage['optional_discovery'],'assignments':assign,'provider_directory':stage['provider_directory'],'source_rights':stage['source_rights']},ensure_ascii=False,indent=2),encoding='utf-8')
# Update project roadmap and README.
roadmap='''# IELTS Boost — Final 10-Stage Roadmap (Renumbered with User’s Resource Stage)\n\nThe work expanded beyond the original ten-stage estimate. The remaining delivery path is fixed at Stages 46–50 so that approved requirements are not renumbered or lost.\n\n| Stage | Final name | Original plan mapping | Status |\n|---:|---|---|---|\n| 46 | Adaptive Learning & Intelligence Engine | Original Stage 6 | Completed; local evidence-based rules, not generative AI |\n| 47 | Resource Integration & Task 1 Visual Intelligence | Original Stage 7 | Implemented; static/data/HTTP QA passed; physical-device checks remain |\n| 48 | Vocabulary & Resource Intelligence | Original Stage 8 | Planned |\n| 49 | UI/UX, Security, PWA & Performance Hardening | Original Stage 9 | Planned |\n| 50 | Full Regression, Device Acceptance & Final Release | Original Stage 10 | Planned |\n\n## Stage 47 delivery summary\n\n1. **All 84 days × 4 compulsory skills = 336 in-app resource slots** are retained and surfaced in the app. Reading passages/questions, Listening MP3/script/questions, Writing Task 1 visuals/Task 2 prompts, and Speaking Part 1/2/3 content remain the required core. The 61-article library remains supplementary.\n2. **Listening:** 84 day-specific official companion assignments with exact title, provider URL, editorial level estimate, focus, task, caption/transcript note, suitability note, rights mode and in-app fallback. There are 28 unique resources in the 84-day sequence, revisited with different listening focuses; the curated catalogue contains 36 named entries. TED-Ed, TED, Huberman Lab and The Diary of a CEO appear in the daily sequence. Joe Rogan Experience is present on the optional discovery shelf only and requires adult preview; it is not compulsory.\n3. **Task 1:** 84 original fictional datasets across six visual families (14 each): line graph, bar chart, pie chart, table, process and map. Added six-type teaching guides, exact data inspector, calculated factual summaries/overview prompts, four-section planning board, minimum-150-word reminder and accuracy audit. The checker validates data structure only; it does not grade semantic writing or assign an IELTS band.\n4. **Writing Task 2** prompts and the existing day-specific Speaking prompts remain intact.\n5. **Rights:** no Barron’s charts/questions/pages are copied. No TED/TED-Ed/podcast media or transcripts are downloaded/re-hosted. Only official provider links are used; the local IELTS Boost MP3s remain original synthetic-voice practice.\n6. Deliverables: 84-row listening mapping, 336-row four-skill resource audit, 84-row Task 1 visual audit, catalog JSON and QA report.\n\n## Stage 47 verified counts\n\n- 84/84 day-specific optional listening companions; 28 unique assignments, 36 catalog resources.\n- Provider distribution in compulsory daily companion sequence: TED-Ed 33 slots, TED 35, Huberman Lab 10, The Diary of a CEO 6. Joe Rogan is optional preview-only.\n- 84/84 Task 1 datasets pass the structural validator; six types × 14 each.\n- 84/84 Task 2 prompts and 84/84 daily Reading, Listening and Speaking content sets remain.\n- 84 bundled Listening MP3 files retained.\n- All five requested provider families are documented; only four are assigned into the daily path due age/content-preview caution for JRE.\n\n## Stage 47 acceptance notes and limitations\n\n- External videos are optional extensions. They do not replace the in-app daily audio, script and question sets.\n- CEFR labels are editorial estimates, not provider-certified labels. Durations and captions can change; individual player controls remain authoritative.\n- Long-form Huberman/DOAC selections use timecodes where verified; other titles direct learners to the official player and its current duration/captions.\n- JRE is optional discovery only and must be previewed by a parent/teacher for age suitability.\n- TED/TED-Ed use official pages/links only. TED content must not be edited, truncated, downloaded or transcript-republished; certain structured/commercial curricular uses may require a licence. TED-Ed videos are copyrighted; no downloading, editing or re-uploading.\n- Full browser E2E, Samsung A14 microphone/PWA/offline acceptance and actual playback on the user's phone remain outstanding.\n\n## Stages 48–50\n\n- **Stage 48:** complete sense-checked vocabulary definitions, Uzbek meanings, original examples, part of speech, US/UK IPA and transparent CEFR/source provenance.\n- **Stage 49:** mobile-first UX, accessibility, security/privacy, PWA/offline, backup/restore, performance and deployment-path hardening.\n- **Stage 50:** full content and feature regression; browser E2E; Samsung A14 transcript, PWA, offline and restore acceptance; final broken-link review and release ZIP/hash.\n'''
(ROOT/'ROADMAP_STAGE46_TO_50_UZ.md').write_text(roadmap,encoding='utf-8')

readme='''# IELTS Boost — Stage 47 Resource Integration Release\n\n## Nima yangilandi\n\n- 84 kun × 4 majburiy skill = 336 in-app resource slotlari.\n- 84 kun uchun individual tanlangan rasmiy Listening companion havolalari; har birida provider, mavzu, editorial CEFR estimate, fokus, topshiriq, caption/transcript holati, suitability va ichki audio fallback ko‘rsatiladi.\n- 36 nomlangan resursli curated catalog; 84 kunlik yo‘lda 28 ta noyob resurs turli tinglash maqsadlari bilan qayta ishlatiladi.\n- TED-Ed, TED, Huberman Lab va The Diary of a CEO kundalik yo‘lda. Joe Rogan Experience faqat ixtiyoriy, adult preview talab qiluvchi discovery shelf’da.\n- 84 ta Task 1 vizual: line graph, bar chart, pie chart, table, process, map — har biridan 14 tadan.\n- Task 1 Visual Intelligence masterclass: chart-specific structure, data inspector, hisoblangan faktlar, overview modeli, 4 qismli planning board, 150+ so‘z eslatmasi va aniqlik auditi.\n- Barron’s grafiklari, savollari yoki kitob sahifalari ko‘chirilmagan. Barcha Task 1 datasets — original fictional practice.\n- Mavjud 84 kunlik asosiy MP3/script/savol va 61 maqola kutubxonasi saqlandi.\n\n## Fayl tuzilmasi\n\n- `index.html` — asosiy ilova shell\n- `assets/css/` — umumiy va Stage 47 stillari\n- `assets/js/app.js` — ilova runtime\n- `assets/js/core/task1-intelligence.js` — Task 1 visual/data analysis\n- `data/app-data.json` — 84 kunlik kontent va resource mapping\n- `data/stage47-resource-catalog.json` — curated external resource catalog\n- `audio/` — 84 ta original synthetic-voice Listening MP3\n- `STAGE47_RESOURCE_MAPPING_UZ.csv` — 84 kunlik external Listening mapping\n- `STAGE47_336_SKILL_RESOURCE_AUDIT_UZ.csv` — barcha 4 skill bo‘yicha 336 qator\n- `STAGE47_TASK1_84_VISUAL_AUDIT_UZ.csv` — 84 ta Task 1 vizual audit\n- `tools/qa_stage47.py`, `tools/qa_stage47.mjs` — Stage 47 QA\n\n## Ishga tushirish\n\n1. ZIP’ni to‘liq extract qiling.\n2. Barcha fayl/papkalarni GitHub repository root’ga joylang.\n3. GitHub Settings → Pages → Deploy from a branch → `main` → `/(root)`.\n4. `DEPLOY_TARGET.txt` va `manifest.webmanifest` ichidagi project path repository nomiga mosligini tekshiring. Hozirgi build `/plan-b-/` yo‘liga sozlangan; repository nomi boshqacha bo‘lsa, deploydan oldin manifest/start_url/scope va Service Worker yo‘llarini moslashtiring.\n5. HTTPS orqali oching; PWA/audio/microphone funksiyalari `file://` rejimida to‘liq ishlamaydi.\n\n## QA\n\n`python tools/qa_stage47.py`\n`node tools/qa_stage47.mjs`\n\nStage 47 static/data/HTTP smoke test va Task 1 engine logic testlarini bajaradi. U haqiqiy Android mikrofon, Chrome SpeechRecognition, TED/YouTube playback, offline install yoki to‘liq browser E2E o‘rnini bosmaydi. Bular Stage 50 acceptance’da bajarilishi kerak.\n\n## Muhim cheklovlar\n\n- IELTS Boost 0–10 practice score rasmiy IELTS bandi emas.\n- Task 1 data inspector va planning checker strukturani hamda raqamlarni ko‘rsatadi; yozuvning semantik sifati, grammatik to‘g‘riligi va IELTS bandini mustaqil tasdiqlamaydi.\n- Tashqi video link/caption/duration o‘zgarishi mumkin; rasmiy playerdagi hozirgi holatga amal qiling.\n- TED/TED-Ed/podcast media yuklab olinmagan yoki qayta joylanmagan. Faqat rasmiy sahifalarga havolalar berilgan.\n- JRE ixtiyoriy preview-only; majburiy o‘quv yo‘liga kiritilmagan.\n'''
(ROOT/'README_UZ.md').write_text(readme,encoding='utf-8')
# Refresh Android quick note.
android='''# Android / Samsung A14 — Stage 47 install & acceptance\n\n1. ZIP’ni extract qiling va barcha fayllarni GitHub repository root’ga yuklang.\n2. GitHub Pages `main` / root’dan publish qiling.\n3. Repository path `plan-b-` emas bo‘lsa, manifest va Service Worker scope’ni o‘zgartirishdan oldin moslashtirish kerak.\n4. Chrome’da HTTPS saytni oching, birinchi yuklanish va Service Worker cache tugashini kuting, keyin refresh qiling.\n5. Chrome menyusidan Install app / Add to Home screen. Android PWA install taklifini ko‘rsatmasa, bu browser/manifest holatiga bog‘liq.\n6. Listening MP3, transcript, microphone permission, audio replay, backup/restore va offline reload’ni telefonning o‘zida sinang.\n7. Stage 47 external videos official provider page orqali ochiladi; player, captions va age controls provider’ga bog‘liq.\n\n**Hali sandbox’da tasdiqlanmagan:** Samsung A14 haqiqiy mikrofon/ASR, PWA install, offline-after-first-load, YouTube/TED playback va restore-from-backup. Stage 50 acceptance checklist’da tasdiqlanadi.\n'''
(ROOT/'ANDROID_INSTALL_UZ.md').write_text(android,encoding='utf-8')
